def dispatch_priority_batch(jobs: list[tuple[int, str]], max_batch: int) -> list[str]:
    if max_batch <= 0 or not jobs:
        return []
    ordered = sorted(jobs, key=lambda x: (-x[0], x[1]))
    return [jid for _, jid in ordered[:max_batch]]

def evaluate_overload_policy(utilization_pct: float, priority: int) -> str:
    if utilization_pct >= 100.0:
        return 'REJECT_429'
    elif utilization_pct > 95.0 and priority < 5:
        return 'ROUTE_1.5B'
    else:
        return 'ROUTE_DEFAULT'
